'use strict';

// ============================================================
// i18n Framework
// ============================================================

// Russian plural helper (3 forms: one, few, many)
function ruPlural(n, one, few, many) {
    var mod100 = Math.abs(n) % 100;
    var mod10 = mod100 % 10;
    if (mod100 >= 11 && mod100 <= 14) return many;
    if (mod10 === 1) return one;
    if (mod10 >= 2 && mod10 <= 4) return few;
    return many;
}

// Arabic plural helper (singular for 1/11+, dual for 2, plural for 3-10)
function arPlural(n, one, two, few, many) {
    if (n === 1) return one;
    if (n === 2) return two;
    if (n <= 10) return n + ' ' + few;
    return n + ' ' + many;
}

function isMacPlatform() {
    return typeof navigator !== 'undefined'
        && typeof navigator.platform === 'string'
        && navigator.platform.indexOf('Mac') !== -1;
}

function platformLabel(macText, otherText) {
    return function () {
        return isMacPlatform() ? macText : otherText;
    };
}

function modifiedClickLabel(baseText, macKey, otherKey) {
    return function () {
        return (isMacPlatform() ? macKey : otherKey) + ' + ' + baseText;
    };
}

